#include <stdio.h>
#define SQUARE(x) ((x) * (x))
#define LIMIT 5
#ifdef DEBUG
#define TRACE(msg) fprintf(stderr, "%s:%d %s\n", __FILE__, __LINE__, msg)
#else
#define TRACE(msg) ((void)0)
#endif

int main(void) {
    int n = SQUARE(LIMIT + 1);   /* ((5 + 1) * (5 + 1)) = 36 */
    TRACE("computed n");
    printf("%d\n", n);
    return 0;
}

